"""Stage 3 finalize: train the chosen surrogate (H=16, alpha=0.1) and pick
per-unit Chebyshev domains — comparing the empirical envelope
(full corpus + 5% margin) against provable interval-arithmetic bounds derived
from the exact feature box. Emits the design artifacts for Stages 4-8."""
import json, sys, warnings
import numpy as np, pandas as pd
import xgboost as xgb
from sklearn.neural_network import MLPRegressor
from sklearn.metrics import roc_auc_score, precision_recall_fscore_support
warnings.filterwarnings("ignore")

REPO = sys.argv[1] if len(sys.argv) > 1 else "."
ART = f"{REPO}/model/surrogate"
TH = float(np.log(0.64 / 0.36))
sig = lambda x: 1 / (1 + np.exp(-x))

fc = json.load(open(f"{REPO}/model/feature_cols.json"))
tr = pd.read_parquet(f"{REPO}/data/cdc_diabetes_train.parquet")
te = pd.read_parquet(f"{REPO}/data/cdc_diabetes_test.parquet")
fu = pd.read_parquet(f"{REPO}/data/cdc_diabetes_prepped.parquet")
Xtr, ytr = tr[fc].to_numpy(np.float32), tr["Diabetes_binary"].to_numpy()
Xte, yte = te[fc].to_numpy(np.float32), te["Diabetes_binary"].to_numpy()
Xfu = fu[fc].to_numpy(np.float32)

m = xgb.XGBClassifier(); m.load_model(f"{REPO}/model/xgb_diabetes_model.json")
p_te = m.predict_proba(Xte)[:, 1]; lg_te = np.log(p_te / (1 - p_te))
p_tr = np.clip(m.predict_proba(Xtr)[:, 1], 1e-7, 1 - 1e-7)
lg_tr = np.log(p_tr / (1 - p_tr))

mu, sd = Xtr.mean(0), Xtr.std(0)
Ztr, Zte, Zfu = (Xtr - mu) / sd, (Xte - mu) / sd, (Xfu - mu) / sd

mlp = MLPRegressor(hidden_layer_sizes=(16,), activation="logistic",
                   solver="adam", alpha=0.1, batch_size=512,
                   learning_rate_init=1e-3, max_iter=60, early_stopping=True,
                   n_iter_no_change=8, validation_fraction=0.1, random_state=42)
mlp.fit(Ztr, lg_tr)
W1, W2 = mlp.coefs_; b1 = mlp.intercepts_[0]; b2 = float(np.ravel(mlp.intercepts_[1])[0])
W2 = W2.ravel()

# ---- exact feature box (survey code books — airtight by domain knowledge) ----
BOX = {"BMI": (12, 98), "MentHlth": (0, 30), "PhysHlth": (0, 30),
       "GenHlth": (1, 5), "Age": (1, 13), "Education": (1, 6), "Income": (1, 8)}
box_lo = np.array([BOX.get(c, (0, 1))[0] for c in fc], float)
box_hi = np.array([BOX.get(c, (0, 1))[1] for c in fc], float)
zlo, zhi = (box_lo - mu) / sd, (box_hi - mu) / sd

# provable per-unit pre-activation bounds (interval arithmetic over the box)
Wp, Wn = np.maximum(W1, 0), np.minimum(W1, 0)
prov_lo = zlo @ Wp + zhi @ Wn + b1
prov_hi = zhi @ Wp + zlo @ Wn + b1

# empirical envelope over full corpus + 5% margin
pre_fu = Zfu @ W1 + b1
span = pre_fu.max(0) - pre_fu.min(0)
emp_lo, emp_hi = pre_fu.min(0) - .05 * span, pre_fu.max(0) + .05 * span

def eval_domains(dom_lo, dom_hi, deg, Z, name):
    pre = Z @ W1 + b1
    hid = np.empty_like(pre)
    coefs = []
    for j in range(pre.shape[1]):
        xs = np.linspace(dom_lo[j], dom_hi[j], 4097)
        cf = np.polynomial.Chebyshev.fit(xs, sig(xs), deg, domain=[dom_lo[j], dom_hi[j]])
        coefs.append(cf.coef.tolist())
        hid[:, j] = cf(pre[:, j])
    plg = (hid @ W2 + b2).ravel()
    lg_exact = (sig(pre) @ W2 + b2).ravel()
    pr, rc, f1, _ = precision_recall_fscore_support(
        yte, (plg >= TH).astype(int), average="binary", zero_division=0)
    return {"name": name, "deg": deg,
            "auc": float(roc_auc_score(yte, sig(plg))),
            "f1": float(f1), "recall": float(rc), "precision": float(pr),
            "agree_exact": float(((plg >= TH) == (lg_exact >= TH)).mean()),
            "max_lgerr": float(np.abs(plg - lg_exact).max()),
            "domain_widths": [float(h - l) for l, h in zip(dom_lo, dom_hi)]}, coefs

res_emp, coef_emp = eval_domains(emp_lo, emp_hi, 27, Zte, "empirical+5%")
res_prov, coef_prov = eval_domains(prov_lo, prov_hi, 27, Zte, "provable_box")

# exact-sigmoid surrogate metrics (the new reference quality)
lg_hat = (sig(Zte @ W1 + b1) @ W2 + b2).ravel()
pr, rc, f1, _ = precision_recall_fscore_support(
    yte, (lg_hat >= TH).astype(int), average="binary", zero_division=0)
base = {"auc": float(roc_auc_score(yte, sig(lg_hat))), "f1": float(f1),
        "recall": float(rc), "precision": float(pr),
        "agree_xgb": float(((lg_hat >= TH) == (lg_te >= TH)).mean())}

# choose: provable if accuracy is essentially unharmed (airtight decode safety
# under batched packing outweighs a <0.01% agreement delta)
use_prov = (res_prov["f1"] >= res_emp["f1"] - 1e-3 and
            res_prov["max_lgerr"] < 0.05)
dom_lo, dom_hi = (prov_lo, prov_hi) if use_prov else (emp_lo, emp_hi)
coefs = coef_prov if use_prov else coef_emp

json.dump({"feature_cols": fc, "mu": mu.tolist(), "sd": sd.tolist(),
           "W1": W1.tolist(), "b1": b1.tolist(), "W2": W2.tolist(), "b2": b2,
           "hidden": 16, "alpha": 0.1, "cheb_degree": 27,
           "domain_kind": "provable_box" if use_prov else "empirical+5%",
           "dom_lo": dom_lo.tolist(), "dom_hi": dom_hi.tolist(),
           "cheb_coefs": coefs, "threshold_logit": TH, "threshold_proba": 0.64},
          open(f"{ART}/mlp_surrogate.json", "w"))
pd.DataFrame({"feature": fc, "min": box_lo, "max": box_hi}).to_csv(
    f"{ART}/feature_bounds.csv", index=False)
json.dump({"surrogate_exact": base, "poly_empirical": res_emp,
           "poly_provable": res_prov, "chosen": "provable_box" if use_prov else "empirical+5%",
           "prov_bounds_absmax": float(max(-prov_lo.min(), prov_hi.max())),
           "emp_bounds_absmax": float(max(-emp_lo.min(), emp_hi.max()))},
          open(f"{ART}/stage3_report.json", "w"), indent=1)

print(json.dumps({"surrogate": base,
                  "emp": {k: res_emp[k] for k in ("auc", "f1", "agree_exact", "max_lgerr")},
                  "prov": {k: res_prov[k] for k in ("auc", "f1", "agree_exact", "max_lgerr")},
                  "prov_absmax": float(max(-prov_lo.min(), prov_hi.max())),
                  "emp_absmax": float(max(-emp_lo.min(), emp_hi.max())),
                  "chosen": "provable_box" if use_prov else "empirical+5%"}, indent=1))
